<script setup>
import { computed } from 'vue'
import Icon from './GardenIcon.vue'
import { securityLabel, securityReason, nativeScanLabel } from './securityRuntime.js'
import { sizeText, dateText, cap } from './nativeModel.js'
const props=defineProps({mod:Object,item:Object,detail:Object,loading:Boolean,scanning:Boolean,writeAllowed:Boolean,dirty:Boolean})
defineEmits(['action'])
const label=computed(()=>securityLabel(props.item)),report=computed(()=>props.detail?.report)
const reasons=computed(()=>['unscanned','scanning'].includes(props.item?.state)?[]:[...new Set([...(props.item?.blocking_reasons||[]),...(props.item?.review_reasons||report.value?.blocking_reasons||[])])].filter(reason=>reason!=='SECURITY_HIGH_RISK'))
const kindNames={pe:'可执行格式（含内嵌资源）',media:'图片与音频',managed:'托管程序集',managed_pe:'托管程序集',native:'原生程序',native_pe:'原生程序',image:'图片',audio:'音频',archive:'归档',script:'脚本',manifest:'清单',json:'JSON 数据',data:'数据',other:'其他',unknown:'未识别'}
const composition=computed(()=>Object.entries(report.value?.stats?.by_kind||{}).map(([kind,value])=>({kind,label:kindNames[kind]||kind,bytes:typeof value==='number'?value:value.bytes??value.total_bytes,count:typeof value==='object'?value.count??value.file_count:null})))
const antivirus=computed(()=>report.value?.antivirus)
const avLabel=computed(()=>({not_scanned:'尚未运行',scanning:'扫描中',clean:'未检出威胁',completed:'扫描完成',detected:'检出威胁',threat_found:'检出威胁',unavailable:'引擎不可用',failed:'扫描失败',timeout:'扫描超时',incomplete:'扫描未完成'})[antivirus.value?.state]||antivirus.value?.state||'尚未运行')
const changed=computed(()=>report.value?.diff)
const pathOf=file=>typeof file==='string'?file:file.path
const coverage=computed(()=>report.value?.coverage)
const nativeScan=computed(()=>report.value?.native_scan),nativeLabel=computed(()=>nativeScanLabel(nativeScan.value))
const action=kind=>({kind})
</script>
<template>
  <div class="native-security" data-testid="mod-security-detail">
    <div class="security-conclusion" :class="label.tone" role="status"><span class="tg" :class="label.tone"><Icon name="shield" size="xs"/>{{ label.label }}</span><p>{{ label.next }}</p><small v-if="item?.scanned_at">检查于 {{ dateText(item.scanned_at) }}</small><p v-if="item?.state==='stale'" class="muted">下面保留的是旧内容报告，不适用于当前文件。</p><ul v-if="reasons.length"><li v-for="(reason,i) in reasons" :key="i">{{ securityReason(reason) }}</li></ul><div class="note-act"><button data-testid="security-scan-mod" class="garden-btn green sm" :disabled="scanning" @click="$emit('action',action('security-scan'))">{{ scanning?'正在检查…':'检查当前内容' }}</button><button class="garden-link" @click="$emit('action',action('security-refresh'))">刷新报告</button></div></div>
    <div v-if="loading&&!report" class="garden-empty" role="status">正在读取本地检查报告…</div>
    <p v-else-if="!report" class="muted security-empty">检查完整本地包后，这里会显示组成、变化、证据和覆盖范围。游戏批准与本地检查分别记录。</p>
    <template v-if="report">
      <div v-if="nativeScan" class="sec" data-testid="security-native-scan"><h3>游戏原生检查 <span class="tg" :class="nativeLabel.tone">{{ nativeLabel.label }}</span></h3><template><p v-if="nativeScan.error" class="care-note">{{ securityReason(nativeScan.error) }}</p><p v-if="nativeScan.undeclared?.length" class="care-note">清单未声明的权限：{{ nativeScan.undeclared.map(value=>cap(value).label).join('、') }}。请结合模组用途复核，由你决定是否停用或隔离。</p><dl class="garden-facts"><dt>已检查方法</dt><dd>{{ nativeScan.methods_scanned??'未知' }}</dd><dt>检测权限</dt><dd>{{ Array.isArray(nativeScan.capabilities)?nativeScan.capabilities.length?nativeScan.capabilities.map(value=>cap(value).label).join('、'):'未检出权限':'未取得结果' }}</dd></dl><article v-for="(flag,i) in nativeScan.hard_flags||[]" :key="i" class="security-finding"><div><span class="tg bad">拒绝项</span><b>{{ flag.kind }}</b></div><code>{{ flag.location }}</code><p>{{ flag.target }}</p></article><details v-if="nativeScan.findings?.length" class="security-tech"><summary>原生检查证据 · {{ nativeScan.findings.length }} 项</summary><div v-for="(finding,i) in nativeScan.findings" :key="i" class="security-evidence"><b>{{ finding.kind }}</b><code>{{ finding.location }}</code><p>{{ finding.target }}</p></div></details><details v-if="nativeScan.files?.length" class="security-tech"><summary>检查文件与扫描器标识</summary><div v-for="file in nativeScan.files" :key="file.path" class="security-file"><code>{{ file.path }}</code><span>{{ sizeText(file.size) }}</span></div><code class="security-hash">{{ nativeScan.scanner_identity }}</code></details></template></div>
      <div class="sec"><h3>内容组成 <small>{{ report.stats?.file_count ?? report.files?.length }} 个文件 · {{ sizeText(report.stats?.total_bytes) }}</small></h3><div class="security-composition"><div v-for="part in composition" :key="part.kind"><span>{{ part.label }}<small v-if="part.count!=null"> · {{ part.count }} 个</small></span><b>{{ sizeText(part.bytes) }}</b><div class="garden-solar"><i :style="{width:report.stats?.total_bytes?Math.min(100,part.bytes/report.stats.total_bytes*100)+'%':'0%'}"></i></div></div></div><p v-if="report.stats?.embedded_resource_bytes!=null" class="muted">程序集内嵌资源 {{ sizeText(report.stats.embedded_resource_bytes) }}，已包含在对应文件大小中，不重复累计。</p><details v-if="report.stats?.largest_files?.length" class="security-tech"><summary>最大的文件</summary><div v-for="file in report.stats.largest_files" :key="file.path" class="security-file"><code>{{ file.path }}</code><span>{{ sizeText(file.size??file.size_bytes) }}</span></div></details></div>
      <details v-if="report.stats?.method_il_bytes!=null" class="security-tech"><summary>程序集体积明细</summary><dl class="garden-facts"><dt>方法 IL</dt><dd>{{ sizeText(report.stats.method_il_bytes) }}</dd><dt>元数据</dt><dd>{{ sizeText(report.stats.metadata_bytes) }}</dd><dt>内嵌资源</dt><dd>{{ report.stats.resource_count??'未知' }} 项 · {{ sizeText(report.stats.embedded_resource_bytes) }}</dd></dl><p class="muted">这些是可解析部分的组成，不代表 DLL 的全部体积。资源体积大不等于代码行为多。</p></details>
      <div class="sec"><h3>与上次检查相比</h3><p v-if="!changed?.baseline_report_id" class="muted">首次检查，还没有可比较的内容基线。</p><template v-else><div class="security-diff-counts"><span class="tg on">新增 {{ changed.added?.length||0 }}</span><span class="tg off">删除 {{ changed.removed?.length||0 }}</span><span class="tg pend">修改 {{ changed.modified?.length||0 }}</span></div><p class="muted">总量变化 {{ changed.byte_delta<0?'−':'+' }}{{ sizeText(Math.abs(changed.byte_delta||0)) }} · {{ changed.unchanged_count||0 }} 个文件未变</p><details v-for="[key,title] in [['added','新增文件'],['removed','删除文件'],['modified','修改文件']]" v-show="changed[key]?.length" :key="key" class="security-tech"><summary>{{ title }} · {{ changed[key]?.length }}</summary><div v-for="file in changed[key]" :key="pathOf(file)" class="security-file"><code>{{ pathOf(file) }}</code><span v-if="file.before_size!=null&&file.after_size!=null">{{ sizeText(file.before_size) }} → {{ sizeText(file.after_size) }}</span></div></details></template></div>
      <div class="sec"><h3>具体风险证据 <small>{{ report.findings?.length||0 }} 项</small></h3><p v-if="!report.findings?.length" class="muted">当前报告没有规则命中；请同时查看覆盖范围。</p><article v-for="finding in report.findings" :key="finding.id" class="security-finding"><div><span class="tg" :class="['high','critical'].includes(finding.severity)?'bad':finding.severity==='info'?'sky':'pend'">{{ ({critical:'严重',high:'高风险',medium:'需复核',warning:'需复核',low:'提示',info:'能力提示'})[finding.severity]||finding.severity }}</span><b>{{ finding.title }}</b></div><p>{{ securityReason(finding.basis) }}</p><details class="security-tech"><summary>查看定位与证据</summary><div v-for="(evidence,i) in finding.evidence" :key="i" class="security-evidence"><code>{{ evidence.path }}<template v-if="evidence.method"> · {{ evidence.method }}</template><template v-if="evidence.offset!=null"> · IL {{ evidence.offset }}</template></code><p>{{ evidence.detail }}</p></div><small>规则 {{ finding.rule }} · 证据 {{ finding.id }}</small></details></article></div>
      <div class="sec"><h3>检查覆盖</h3><dl class="garden-facts"><dt>完整文件读取</dt><dd>{{ coverage?.files_hashed??'未知' }} / {{ coverage?.files_total??'未知' }}</dd><dt>PE 静态解析</dt><dd>{{ coverage?.pe_scanned??'未知' }} / {{ coverage?.pe_total??'未知' }}</dd><dt>覆盖状态</dt><dd>{{ ({complete:'已完成',partial:'部分完成',incomplete:'未完成'})[coverage?.status]||coverage?.status||'未知' }}</dd></dl><ul v-if="coverage?.gaps?.length" class="security-gaps"><li v-for="(gap,i) in coverage.gaps" :key="i">{{ securityReason(gap) }}</li></ul><details class="security-tech"><summary>检查标识与全包文件清单</summary><p v-if="report.rule_version">规则版本 {{ report.rule_version }}</p><p class="muted">内容指纹用于将报告绑定到本次文件，不代表安全认证。</p><code class="security-hash">{{ item?.content_hash }}</code><div v-for="file in report.files" :key="file.path" class="security-file"><code>{{ file.path }}</code><span>{{ sizeText(file.size) }}</span></div></details></div>
      <details v-if="coverage?.limitations?.length||report.assemblies?.length" class="security-tech"><summary>静态分析范围与逐文件结果</summary><ul v-if="coverage?.limitations?.length" class="security-gaps"><li v-for="limit in coverage.limitations" :key="limit">{{ securityReason(limit) }}</li></ul><div v-for="assembly in report.assemblies" :key="assembly.path" class="security-evidence"><code>{{ assembly.path }}</code><p>{{ assembly.error?securityReason(assembly.error):({managed:'托管静态解析完成',native:'原生格式，未分析行为',hash_only:'仅完成文件指纹读取'})[assembly.status]||assembly.status }}</p></div></details>
    </template>
    <div class="sec"><h3>Microsoft Defender <span class="tg off">{{ avLabel }}</span></h3><p v-if="antivirus?.reason||antivirus?.message">{{ securityReason(antivirus.reason||antivirus.message) }}</p><dl v-if="antivirus?.engine||antivirus?.signature_time" class="garden-facts"><dt>引擎</dt><dd>{{ antivirus.engine||'未知' }}</dd><dt>签名时间</dt><dd>{{ antivirus.signature_time?dateText(antivirus.signature_time):'未取得' }}</dd></dl><div v-if="antivirus?.detections?.length" class="care-note"><p v-for="(detection,i) in antivirus.detections" :key="i">{{ securityReason(detection) }}</p></div><p v-if="antivirus?.checked_at" class="muted">扫描于 {{ dateText(antivirus.checked_at) }}</p><p class="muted">手动扫描，不自动处置，不由管理器上传样本。Defender 的云保护遵循你的 Windows 设置。</p><button data-testid="security-defender" class="garden-btn sm" :disabled="scanning" @click="$emit('action',action('security-defender'))">运行 Defender 无处置扫描…</button></div>
    <div class="sec"><h3>可恢复处置</h3><p v-if="mod.source==='workshop'" class="muted">工坊隔离仅停用并阻止管理器受控启动，文件仍在 Steam 工坊；不移走文件、不取消订阅。</p><p v-else class="muted">本地隔离先备份，再将包移出游戏扫描范围。恢复不会自动启用，也不会恢复批准。</p><div class="note-act"><button data-testid="security-disable" class="garden-btn sm" :disabled="!writeAllowed||dirty||scanning" @click="$emit('action',action('security-disable'))">停用并查看影响…</button><button data-testid="security-quarantine" class="garden-btn clay sm" :disabled="!writeAllowed||dirty||scanning" @click="$emit('action',action('security-quarantine'))">{{ mod.source==='workshop'?'逻辑隔离…':'备份并隔离…' }}</button><button class="garden-link" @click="$emit('action',action('security-records'))">处置与恢复记录</button></div><p v-if="dirty" class="muted">先保存或放弃启用草稿，再执行处置，以免覆盖你的调整。</p><p v-else-if="!writeAllowed" class="muted">当前不能写入；请等待游戏退出、本地操作和状态核对完成。</p></div>
  </div>
</template>
